// Generated by AI (UnitTest MCP)
//! Design items (ADR-0023): an ADR under human review.
//!
//! A design item references an ADR file and carries that ADR's lifecycle: the
//! *taint* is the ADR's `Proposed` status. While proposed it is **not**
//! claimable and never appears in `next_task` or the executive board — it lives
//! on the Design Board. A human `accept`/`reject` is the completion path for
//! design work; unlike an implementation task it does **not** run ADR-0009 code
//! conformance (there is no code for a design decision to conform to). Rejection
//! is durable and auditable — archived, never deleted (ADR-0019).

use serde::{Deserialize, Serialize};

use crate::model::{Goal, GoalKind, Task};

/// Where a design item sits in its human-review lifecycle.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "lowercase")]
pub enum DesignStatus {
    /// Tainted: awaiting a human decision. On the Design Board, off the
    /// executive board.
    Proposed,
    /// A human accepted the design; it is the completion of design work.
    Accepted,
    /// A human rejected the design; durable and auditable, spawns no work.
    Rejected,
}

impl DesignStatus {
    pub fn as_str(&self) -> &'static str {
        match self {
            DesignStatus::Proposed => "proposed",
            DesignStatus::Accepted => "accepted",
            DesignStatus::Rejected => "rejected",
        }
    }

    pub fn from_tag(s: &str) -> Option<Self> {
        match s {
            "proposed" => Some(DesignStatus::Proposed),
            "accepted" => Some(DesignStatus::Accepted),
            "rejected" => Some(DesignStatus::Rejected),
            _ => None,
        }
    }

    /// A proposed item is the only state a human decision may act on.
    pub fn is_open(&self) -> bool {
        matches!(self, DesignStatus::Proposed)
    }
}

/// Whether an accepted design still needs to materialize implementation work.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "snake_case")]
pub enum DesignPromotionStatus {
    /// Rejected, proposed, or historical work that should not create tasks.
    NotRequired,
    /// Accepted by a human and waiting for an idempotent promotion attempt.
    Pending,
    /// Objective/constraint goals and implementation tasks were persisted.
    Materialized,
}

impl DesignPromotionStatus {
    pub fn as_str(&self) -> &'static str {
        match self {
            DesignPromotionStatus::NotRequired => "not_required",
            DesignPromotionStatus::Pending => "pending",
            DesignPromotionStatus::Materialized => "materialized",
        }
    }

    pub fn from_tag(value: &str) -> Option<Self> {
        match value {
            "not_required" => Some(DesignPromotionStatus::NotRequired),
            "pending" => Some(DesignPromotionStatus::Pending),
            "materialized" => Some(DesignPromotionStatus::Materialized),
            _ => None,
        }
    }
}

/// Why a design record left the working board, and who said so (ADR-0042).
///
/// One value object rather than three loose fields: retirement is a single
/// fact, and three parallel `Option`s could disagree — a row retired with no
/// actor, or an actor with no timestamp, would both be representable.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub struct Retirement {
    pub at: i64,
    /// The person who retired it. Never an agent session: retirement is a human
    /// act, because no code path may infer it from a missing file.
    pub by: String,
    pub reason: String,
}

/// A decision that was made, held, and has since been replaced (ADR-0050).
///
/// One value object rather than three loose fields, for the same reason as
/// `Retirement`: supersession is a single fact, and parallel `Option`s could
/// disagree — a replacement with no actor, or an actor with no replacement,
/// would both be representable.
///
/// Deliberately not a `DesignStatus` variant. The design *was* accepted; a
/// status that erased that would lose the decision and could not say what
/// replaced it. This mirrors `Goal::superseded_by`, so there is one vocabulary
/// for supersession rather than two.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub struct Supersession {
    /// The design that replaces this one. Always a registered design: a
    /// dangling reference would leave a reader with a withdrawn decision and
    /// nowhere to go.
    pub by_design: String,
    pub at: i64,
    /// The person who said so. Never inferred from an ADR's prose — deriving it
    /// would repeat ADR-0047's mistake of a file telling the ledger something
    /// nobody is recorded as deciding.
    pub by: String,
}

/// An ADR under review in the Intent Plane.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub struct DesignItem {
    /// Stable id derived from the ADR file, e.g. `design:0023-design-board`.
    pub id: String,
    /// The ADR path, normalised to forward slashes, e.g. `docs/adr/0023-...md`.
    pub adr_path: String,
    pub title: String,
    pub summary: String,
    pub status: DesignStatus,
    /// Agent that registered the item (may not decide its own design).
    pub proposed_by: Option<String>,
    /// Human that accepted or rejected it.
    pub decided_by: Option<String>,
    /// Acceptance/rejection rationale.
    pub reason: Option<String>,
    pub created_at: i64,
    pub updated_at: i64,
    /// Promotion is separate from the human decision so optional planning never
    /// runs while the acceptance transaction is open.
    pub promotion_status: DesignPromotionStatus,
    /// Latest append-only materialization audit revision, or zero before one exists.
    pub materialization_revision: i64,
    /// Set once a person retires the record (ADR-0042). Orthogonal to `status`:
    /// retirement says this row is no longer a live entry, and must not
    /// overwrite what a human decided about the design itself.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub retired: Option<Retirement>,
    /// Set once a person records that this decision has been replaced
    /// (ADR-0050). Orthogonal to `status` for the same reason as `retired`: the
    /// design stays `accepted` because it was accepted. A live design is one
    /// where this is `None`.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub superseded: Option<Supersession>,
}

